// Package indicator defines the activity states a table row's first column can
// show, their glyphs, and the precedence between concurrent sources of state.
// It is pure: no dependency on theme, jobs or datatable.
package indicator

// State is what the first column says about a row. The zero value is Idle (rest).
type State int

const (
	Idle       State = iota // the row's own icon, or an empty cell
	Running                 // blinks; busy counts as Running
	Queued                  // waiting
	Failed                  // op failed, container dead or exited non-zero
	Suspended               // agent idle, container paused
	Restarting              // container restarting
	Done                    // job done, agent done
	Cancelled               // job cancelled
	Skipped                 // job skipped, container exited 0
	Unknown                 // agent unknown, container created
)

// states lists every state but Idle, in declaration order.
var states = []State{Running, Queued, Failed, Suspended, Restarting, Done, Cancelled, Skipped, Unknown}

var names = map[State]string{
	Idle: "idle", Running: "running", Queued: "queued", Failed: "failed",
	Suspended: "suspended", Restarting: "restarting", Done: "done",
	Cancelled: "cancelled", Skipped: "skipped", Unknown: "unknown",
}

var glyphs = map[State]string{
	Queued: "◴", Failed: "⊗", Suspended: "◐", Restarting: "◕",
	Done: "◉", Cancelled: "⊘", Skipped: "⊖", Unknown: "◌",
}

const (
	runningOn  = "●"
	runningOff = "○"
)

// States returns every state but Idle, in declaration order.
func States() []State { return append([]State(nil), states...) }

// Glyph returns the one-rune glyph of s; on is the blink phase (Running only).
// Idle has no glyph and yields an empty string.
func Glyph(s State, on bool) string {
	if s == Running {
		if on {
			return runningOn
		}
		return runningOff
	}
	return glyphs[s]
}

// Animated reports whether s blinks.
func Animated(s State) bool { return s == Running }

// String returns the lowercase name of s.
func (s State) String() string {
	if n, ok := names[s]; ok {
		return n
	}
	return "invalid"
}

// Activity is everything that can be true of one row at once.
type Activity struct {
	Running, Queued, Failed bool  // Failed = a remembered failure
	Observed                State // computed by the view; Idle if none
}

// Resolve applies running > queued > remembered failure > observed > idle.
func Resolve(a Activity) State {
	switch {
	case a.Running:
		return Running
	case a.Queued:
		return Queued
	case a.Failed:
		return Failed
	}
	return a.Observed
}
package indicator

import (
	"strings"

	"github.com/anthnel/devdesk/internal/ui/help"
)

// LegendEntry is one extension row of the legend: a state and its label.
type LegendEntry struct {
	State State
	Label string
}

// legendSectionTitle is the title of the help section every migrated view shows.
const legendSectionTitle = "Activity indicator"

// Legend returns the "Activity indicator" help section: the base rows, then the
// extension rows of the view. Glyphs come from Glyph, never from literals.
func Legend(extension ...LegendEntry) help.Section {
	on, off := Glyph(Running, true), Glyph(Running, false)
	lines := []string{
		"The first column shows what is happening on a row. The glyph carries the",
		"meaning; the color repeats it. Nothing here relies on color alone.",
		"",
		"  " + on + " " + off + "  Running (blinks). Pauses to a steady " + on + " when motion is off.",
		"  " + Glyph(Queued, false) + "  Queued, waiting to start.",
		"  " + Glyph(Failed, false) + "  Failed. Stays until the next attempt on that row; the footer gives the cause.",
		"  (icon)  Idle: the row's usual icon, or an empty cell.",
	}
	for _, e := range extension {
		lines = append(lines, "  "+Glyph(e.State, true)+"  "+e.Label)
	}
	lines = append(lines,
		"",
		"The footer describes the selected row's state in words.",
		"Turn the blinking off with app.motion: static in the context file or in :cfg.",
	)
	return help.Section{Title: legendSectionTitle, Body: strings.Join(lines, "\n")}
}

// Per-view legend extensions (ux.md section 5).
var (
	JobsLegend = []LegendEntry{
		{Done, "done"}, {Cancelled, "cancelled"}, {Skipped, "skipped"},
	}
	CloneLegend = []LegendEntry{
		{Done, "cloned (clone list)"},
		{Skipped, "already on disk, or not started (cancelled) (clone list)"},
	}
	AgentsLegend = []LegendEntry{
		{Suspended, "idle (no activity for 5 min)"}, {Done, "done"}, {Unknown, "unknown"},
	}
	ContainersLegend = []LegendEntry{
		{Restarting, "restarting"}, {Suspended, "paused"}, {Unknown, "created"},
		{Skipped, "exited (code 0)"}, {Failed, "exited (non-zero code) or dead"},
		{Running, "an action (stop, restart, pause, resume, delete) is running"},
	}
)
